select * from (select case when revenue >= 3000 then 'high' when revenue >= 1600 then 'mid' else 'low' end as revenue_bucket, store_id, round(avg(revenue), 2) as avg_revenue, count(distinct units) as unique_products from store_sales group by case when revenue >= 3000 then 'high' when revenue >= 1600 then 'mid' else 'low' end, store_id) as s where avg_revenue >= 45 order by revenue_bucket desc, store_id desc limit 5;
